import axios from 'axios';
import React, { useState, useEffect } from 'react';

function ToDoList() {

    const [tasks, setTasks] = useState([]);
    const [newTask, setNewTask] = useState("");
    const [searchTerm, setSearchTerm] = useState('');

    // ✅ Load tasks from MongoDB on load
    useEffect(() => {
        async function fetchTasks() {
            try {
                const response = await axios.get('http://localhost:5001/tasks');
                setTasks(response.data);
            } catch (error) {
                console.error('Error fetching tasks:', error);
            }
        }
        fetchTasks();
    }, []);

    function handleSearchChange(event) {
        setSearchTerm(event.target.value);
    }

    // ✅ Filter tasks based on MongoDB object structure
    const filteredTasks = tasks.filter(task =>
        task.text.toLowerCase().includes(searchTerm.toLowerCase())
    );

    function handleInputChange(event) {
        setNewTask(event.target.value);
    }

    // ✅ Add task to MongoDB
    async function addTask() {
        if (newTask.trim() !== "") {
            try {
                const response = await axios.post('http://localhost:5001/tasks', { text: newTask });
                setTasks([...tasks, response.data]);
                setNewTask("");
            } catch (error) {
                console.error('Error adding task:', error);
            }
        }
    }

    // ✅ Delete task from MongoDB
    async function deleteTask(id) {
        try {
            await axios.delete(`http://localhost:5001/tasks/${id}`);
            setTasks(tasks.filter(task => task._id !== id));
        } catch (error) {
            console.error('Error deleting task:', error);
        }
    }

    // ✅ Move task up in MongoDB order
    async function moveTaskUp(index) {
        if (index > 0) {
            try {
                const response = await axios.put('http://localhost:5001/tasks/reorder', {
                    sourceIndex: index,
                    destinationIndex: index - 1
                });
                setTasks(response.data);
            } catch (error) {
                console.error('Error moving task up:', error);
            }
        }
    }

    // ✅ Move task down in MongoDB order
    async function moveTaskDown(index) {
        if (index < tasks.length - 1) {
            try {
                const response = await axios.put('http://localhost:5001/tasks/reorder', {
                    sourceIndex: index,
                    destinationIndex: index + 1
                });
                setTasks(response.data);
            } catch (error) {
                console.error('Error moving task down:', error);
            }
        }
    }

    function callConsoleLog() {
        console.log(tasks);
    }

    // ✅ Generate 20,000 tasks and save to MongoDB
    async function generateTasks() {
        const newTasks = Array.from({ length: 20000 }, (_, i) => `Task ${i + 1}`);
        for (const task of newTasks) {
            await axios.post('http://localhost:5001/tasks', { text: task });
        }
        const response = await axios.get('http://localhost:5001/tasks');
        setTasks(response.data);
    }

    return (
        <div className='to-do-list'>
            <h1>To-Do List</h1>

            {/* ✅ Search Bar */}
            <input
                type="text"
                placeholder="Search tasks..."
                value={searchTerm}
                onChange={handleSearchChange}
                className="search-bar"
            />

            {/* ✅ Add Task Section */}
            <div>
                <input
                    type="text"
                    placeholder="Enter a Task.."
                    value={newTask}
                    onChange={handleInputChange}
                />
                <button
                    className="add-button"
                    onClick={addTask}>
                    Add
                </button>
                <button
                    className='move-button'
                    onClick={() => callConsoleLog()}>
                    LOG  
                </button>
                <button
                    className="add-button"
                    onClick={generateTasks}>
                    Generate 20,000 Tasks
                </button>
            </div>

            {/* ✅ Render Filtered Tasks */}
            <ol>
                {filteredTasks.map((task, index) => (
                    <li key={task._id}>
                        <span className='text'>{task.text}</span>
                        <button
                            className='delete-button'
                            onClick={() => deleteTask(task._id)}>
                            Delete
                        </button>
                        <button
                            className='move-button'
                            onClick={() => moveTaskUp(index)}>
                            🔼
                        </button>
                        <button
                            className='move-button'
                            onClick={() => moveTaskDown(index)}>
                            🔽
                        </button>
                    </li>
                ))}
            </ol>
        </div>
    );
}

export default ToDoList;
